CREATE TABLE IF NOT EXISTS math_sympy_build_results (id TEXT PRIMARY KEY, problem_id TEXT NOT NULL REFERENCES math_problems(id), parse_result_id TEXT NOT NULL REFERENCES math_parse_results(id), input_ast_hash TEXT NOT NULL, source_revision INTEGER NOT NULL, builder_version TEXT NOT NULL, sympy_version TEXT NOT NULL, status TEXT NOT NULL, symbol_table_json TEXT NOT NULL, artifact_json TEXT NOT NULL, warnings_json TEXT NOT NULL DEFAULT '[]', errors_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, UNIQUE(parse_result_id,input_ast_hash,builder_version,sympy_version));
CREATE TABLE IF NOT EXISTS math_analysis_reports (id TEXT PRIMARY KEY, problem_id TEXT NOT NULL REFERENCES math_problems(id), parse_result_id TEXT NOT NULL REFERENCES math_parse_results(id), build_result_id TEXT NOT NULL REFERENCES math_sympy_build_results(id), input_ast_hash TEXT NOT NULL, source_revision INTEGER NOT NULL, analysis_version TEXT NOT NULL, status TEXT NOT NULL, report_json TEXT NOT NULL, warnings_json TEXT NOT NULL DEFAULT '[]', errors_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, UNIQUE(build_result_id,input_ast_hash,analysis_version));
CREATE INDEX IF NOT EXISTS idx_math_build_current ON math_sympy_build_results(problem_id,source_revision,created_at);
CREATE INDEX IF NOT EXISTS idx_math_analysis_current ON math_analysis_reports(problem_id,source_revision,created_at);
